import XCTest
final class PortfolioUITests:XCTestCase {
 @MainActor func attach(_ app:XCUIApplication,_ name:String){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
 @MainActor func scrollTo(_ item:XCUIElement,_ app:XCUIApplication,down:Bool=false){for _ in 0..<18 where !item.isHittable{if down{app.swipeDown()}else{app.swipeUp()}};XCTAssertTrue(item.isHittable)}
 @MainActor func testALibrary() throws {continueAfterFailure=false;let app=XCUIApplication(bundleIdentifier:"com.apple.mobilesafari");app.activate();let web=app.webViews.firstMatch;XCTAssertTrue(web.waitForExistence(timeout:40));let close=app.buttons["Close"].firstMatch;if close.exists && close.isHittable{close.tap()};let heading=web.staticTexts["One move, one reason"];XCTAssertTrue(heading.waitForExistence(timeout:20));let tr=web.buttons["Türkçe"];XCTAssertTrue(tr.waitForExistence(timeout:8));tr.tap();XCTAssertTrue(web.staticTexts["Bir hamle, bir neden"].waitForExistence(timeout:8));let diagram=web.descendants(matching:.any).matching(NSPredicate(format:"label BEGINSWITH %@", "Vurgulanan çıkarım")).firstMatch;XCTAssertTrue(diagram.waitForExistence(timeout:8));attach(app,"puzzle-library-turkish");web.buttons["English"].tap();let apply=web.buttons["Apply this deduction"].firstMatch;scrollTo(apply,app);attach(app,"puzzle-library-example");apply.tap();XCTAssertTrue(web.buttons["Reset example"].firstMatch.exists);attach(app,"puzzle-library-applied")}
 @MainActor func testBTango() throws {continueAfterFailure=false;let app=XCUIApplication(bundleIdentifier:"com.apple.mobilesafari");app.activate();let web=app.webViews.firstMatch;XCTAssertTrue(web.waitForExistence(timeout:40));let example=web.buttons.matching(NSPredicate(format:"label CONTAINS %@", "Load Example")).firstMatch;XCTAssertTrue(example.waitForExistence(timeout:20));scrollTo(example,app,down:true);example.tap();let explain=web.buttons["Explain my next move"];scrollTo(explain,app);explain.tap();XCTAssertTrue(web.staticTexts.matching(NSPredicate(format:"label CONTAINS %@", "No supported deduction found")).firstMatch.waitForExistence(timeout:8));let saved=web.buttons["Save locally and keep saving changes"];scrollTo(saved,app);saved.tap();XCTAssertTrue(web.staticTexts.matching(NSPredicate(format:"label CONTAINS %@", "Saved on this device")).firstMatch.waitForExistence(timeout:8));attach(app,"puzzle-tango-saved")}
 @MainActor func testCRestoreAndForget() throws {continueAfterFailure=false;let app=XCUIApplication(bundleIdentifier:"com.apple.mobilesafari");app.activate();let web=app.webViews.firstMatch;XCTAssertTrue(web.waitForExistence(timeout:40));let resume=web.buttons["Resume my local board"];XCTAssertTrue(resume.waitForExistence(timeout:20));scrollTo(resume,app);resume.tap();XCTAssertTrue(web.staticTexts.matching(NSPredicate(format:"label CONTAINS %@", "Local saving is on")).firstMatch.waitForExistence(timeout:8));attach(app,"puzzle-tango-restored");let reset=web.buttons["Reset and forget local board"];scrollTo(reset,app);reset.tap();let confirm=web.buttons["Confirm reset and forget local board"];XCTAssertTrue(confirm.waitForExistence(timeout:8));confirm.tap();XCTAssertTrue(web.staticTexts.matching(NSPredicate(format:"label CONTAINS %@", "Local copy removed")).firstMatch.waitForExistence(timeout:8));XCTAssertFalse(resume.exists);attach(app,"puzzle-tango-forgotten")}
}
